  },
  "purpose": "reconcile vendor statement and internal ledger for charge lines using client reference as key and net value within tolerance comparison",
  "sources": {
    "statement": {
      "role_label": "Vendor Charge Summary",
      "fixture": "vendor-charge-summary.txt",
      "observed_fields": ["Charge Period", "Client Ref", "Net Value", "Tax Band", "Settlement State"],
      "basis": "observed"
    },
    "ledger": {
      "role_label": "Internal Charge Ledger",
      "fixture": "internal-charge-ledger.txt",
      "observed_fields": ["Charge Period", "Internal Key", "Client Ref", "Net Value", "Settlement State", "Remarks"],
      "basis": "observed"
    }
  },
  "body": {
    "left": "statement",
    "right": "ledger",
    "match_on": {
      "left_field": "Client Ref",
      "right_field": "Client Ref",
      "basis": "human_confirmed",
      "confirmation": "Q_match_key"
    },
    "compare": [
      {
        "field": "Net Value",
        "comparison": "within",
        "tolerance": "0.01",
        "basis": "human_confirmed",
        "confirmation": "Q_compare_rule"
      }
    ],
    "classify": {
      "both_same": "match on key, net value within tolerance",
      "both_different": "match on key, net value differs beyond tolerance",
      "only_left": "vendor statement has charge not in internal ledger",
      "only_right": "internal ledger has charge not in vendor statement"
    },
    "output_order": "left_then_right",
    "on_duplicate_key": "refuse_key",
    "on_non_numeric": "refuse_key"
  },
  "output": {
    "reports_fields": ["Client Ref", "Net Value"],
    "context_fields": ["Charge Period", "Settlement State"]
  },
  "human_confirmations": [
    {
      "id": "Q_match_key",
      "question": "Which field identifies the same record / charge line in both files?",
      "answer": "Client Ref",
      "basis": "human_confirmed"
    },
    {
      "id": "Q_compare_rule",
      "question": "Should Net Value be compared, and if so, how and with what tolerance? Is Tax Band part of the reconciliation rule? Which file is the source of truth for matching? Which fields should appear in the report row? Which fields are context for the report?",
      "answer": "Yes, compare Net Value numerically, within 0.01. No. Tax Band is recorded on the vendor side only; it is not compared and is not part of the rule. Neither — both are peer sources. Report what is missing from either side and differences in the compared field. The match key (Client Ref) and the compared field (Net Value). Charge Period and Settlement State.",
      "basis": "human_confirmed"
    }
  ],
  "open_questions": [],
  "requested_destination": "review_only",
  "requested_delivery": {
    "format": "json_discrepancy_report"
  },
  "requested_authority": null
}

